{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Disabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server access logging enabled, which prevents auditing of requests made to the bucket and hinders incident response."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Public Access Block Not Configured",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket lacks an explicit aws_s3_bucket_public_access_block resource. Without this, default settings might allow public access depending on account-level configurations or future changes, posing a data exposure risk."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "admin_dashboard" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  rule {
    id     = "expire-old-versions"
    status = "Enabled"

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

resource "aws_s3_bucket_public_access_block" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "admin_dashboard" {
  bucket        = aws_s3_bucket.admin_dashboard.id
  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "log/"
}

# Note: A separate log bucket is required for access logging.
# If one does not exist, it must be created. Adding a minimal log bucket here to satisfy CKV_AWS_18.
resource "aws_s3_bucket" "log_bucket" {
  bucket = "smart-city-parking-management-system-s3-log-bucket-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Added aws_s3_bucket_public_access_block to prevent public exposure (CKV2_AWS_6). Added aws_s3_bucket_logging with a dedicated log bucket to enable access logging (CKV_AWS_18). Also included encryption, versioning, and lifecycle configuration as best practices for security and resilience, though only the first two were strictly flagged by the provided knowledge base entries relevant to the specific risks in the original snippet."
}
